"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class QueueUsingStacks:
    def __init__(self):
        self.stack1 = []
        self.stack2 = []

    def enqueue(self, item):
        self.stack1.append(item)

    def dequeue(self):
        if (len(self.stack2) == 0):
            while (not (len(self.stack1) == 0)):
                temp = self.stack1.pop(-1)
                self.stack2.append(temp)
        if (len(self.stack2) == 0):
            return None
            # LENGTH OF Queue == 0
        return self.stack2.pop(-1)



# ---- Working Example ----

q = QueueUsingStacks()

# Enqueue items
q.enqueue(10)
q.enqueue(20)
q.enqueue(30)

print(q.dequeue())  # 10
print(q.dequeue())  # 20

q.enqueue(40)
q.enqueue(50)

print(q.dequeue())  # 30
print(q.dequeue())  # 40
print(q.dequeue())  # 50
print(q.dequeue())  # None (queue empty)